namespace BlazorNotifications.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly object _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new Notification { Id = _nextId++, Message = "New feature available: Dark Mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) },
        });
    }

    /// <summary>
    /// Returns all notifications available at this moment.
    /// </summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Returns only notifications added after the given timestamp.
    /// Simulates new notifications arriving over time.
    /// </summary>
    public List<Notification> GetSince(DateTime since)
    {
        // Simulate a new notification arriving roughly every 10 seconds
        lock (_lock)
        {
            if (_notifications.Count == 0 || _notifications[^1].Timestamp < DateTime.UtcNow.AddSeconds(-8))
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                    Timestamp = DateTime.UtcNow
                });
            }

            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }
}

@page "/notifications"
@using BlazorNotifications.Services
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

<span class="badge bg-primary fs-5 mb-3 d-inline-block">
    @_notifications.Count notification@(_notifications.Count != 1 ? "s" : "")
</span>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    // OnInitializedAsync runs during BOTH prerender and interactive activation.
    // We load the initial data here so it appears in server-rendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _lastCheck = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    // OnAfterRenderAsync with firstRender==true fires ONLY when the component
    // becomes interactive in the browser — never during static SSR prerender.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
        await base.OnAfterRenderAsync(firstRender);
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newItems = NotificationSvc.GetSince(_lastCheck);
            if (newItems.Count > 0)
            {
                _notifications.AddRange(newItems);
                _lastCheck = newItems.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

